typedef struct
{
  void (*request)(int request, void *arg);
} po_t;

po_t *po;
unsigned char *ambp(void);
unsigned char da;
unsigned char dic;

unsigned char gnda(unsigned char current_address, int sequence);
void rnsm(void);
int state = 0;
static unsigned char *attach_mb_ptr;
static unsigned char ta;
static unsigned char lda;

static unsigned char snod(unsigned char cd, unsigned char *tl, unsigned char *ic)
{
   unsigned char nd;
   while ((nd = gnda(cd,0)) != 0x21)
   {
      int Req;
      po->request(57, &Req);
      if (!Req)
         break;
   }
   if (nd != 0x21)
   {
      switch (nd)
      {
         case 0x95:
            *tl = 0x01;
            break;

         case 0x80:
         case 0x81:
         case 0x82:
            *tl = 0x00;
            break;

         default:
            *tl = 0x05;
            break;
      }
   }
   if (nd != 0x21)
   {
      switch (nd)
      {
         case 0x95:
             *ic = nd - 0x91;
            break;

         case 0x80:
         case 0x81:
         case 0x82:
            *ic = nd - 0x80;	/* compiles into an unconditional store of 0x80 */
            break;

         default:
            *ic = 0;
            break;
      }
   }
   return nd;
}

void rosm3(unsigned char reason)
{
   switch(state)
   {
      case 0:
           attach_mb_ptr = ambp();
           da = snod(0x20, &ta, &dic);
           break;
      case 1:
           lda = da;
           if ((da = snod(lda, &ta, &dic)) != 0x21)
              if (reason == 1)
                 rnsm();
           break;
   }
}
